namespace docking.widgets.filter;



using ghidra.util;

/**
 * A filter that will pass text when it starts with the filter text.
 */
public class StartsWithTextFilter : MatchesPatternTextFilter {

	public StartsWithTextFilter(string filterText, bool caseSensitive, bool allowGlobbing) : base(filterText, caseSensitive, allowGlobbing)
    {
	}

	/* @Override */
	protected Pattern createPattern() {
		int options = Pattern.DOTALL;
		if (!caseSensitive) {
			options |= Pattern.CASE_INSENSITIVE;
		}

		Pattern pattern =
			UserSearchUtils.createStartsWithPattern(filterText, allowGlobbing, options);
		return pattern;
	}

	/* @Override */
	public bool isSubFilterOf(TextFilter parentFilter) {
		if (!(parentFilter is StartsWithTextFilter)) {
			return false;
		}

		StartsWithTextFilter parent = (StartsWithTextFilter) parentFilter;
		if (caseSensitive != parent.caseSensitive || allowGlobbing != parent.allowGlobbing) {
			return false;
		}

		if (parentIsGlobEscape(parent)) {
			return false;
		}

		bool isSubFilter = filterText.startsWith(parent.filterText);
		return isSubFilter;
	}
}
